function main() {
  const filePath = path.resolve('src/i18n/translations.ts')
  let content = fs.readFileSync(filePath, 'utf8')

// Build a block of translations for one language
function buildBlock(lang, keys) {
  const lines = []
  for (const [key, translations] of Object.entries(keys)) {
    const value = translations[lang]
    if (value === undefined) {
      throw new Error(`Missing translation for ${key} in ${lang}`)
    }
    lines.push(`      "${key}": "${value}",`)
  }
  return lines.join('\n') + '\n'
}

// Fix files broken by an earlier injection run (stray comma / missing comma)
for (const lang of langs) {
  // Remove stray comma sitting alone before the language close
  content = content.replace(
    new RegExp(`(      "time\\.directProfileUnavailable": "[^"]+",)\\n,\\n\\n\\},\\n  \\},`, 'g'),
    `$1\n\n},\n  },`
  )
  // Add missing comma after the previous last key when needed
  content = content.replace(
    new RegExp(`("search\\.tryDifferent": "[^"]+")\\n\\n      "common\\.show":`, 'g'),
    `$1,\n\n      "common.show":`
  )
}

// Inject keys into every language block (skip languages that already have the keys)
for (const lang of langs) {
  if (content.includes(`  ${lang}: {`) && content.includes(`"common.show"`)) {
    // Already injected for this language
    continue
  }
  const re = new RegExp(`(  ${lang}: \\{[\\s\\S]*?"search\\.tryDifferent": "[^"]+",)(\\s*\\n\\},\\n  \\},)`, 'm')
  const block = buildBlock(lang, newKeys)
  content = content.replace(re, (match, p1, p2) => `${p1}\n\n${block}${p2}`)
}

  fs.writeFileSync(filePath, content)
  console.log(`Injected ${Object.keys(newKeys).length} keys into ${langs.length} languages`)
}

if (import.meta.url === new URL(process.argv[1], 'file://').href) {
  main()
}

export { newKeys, langs }
